async function fileToImage(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>7e6)throw Error('Choisissez une image JPG, PNG ou WebP de moins de 7 Mo.');const image=await createImageBitmap(file);const scale=Math.min(1,700/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close?.();const value=canvas.toDataURL('image/webp',.76);if(value.length>800000)throw Error('Photo encore trop volumineuse.');return value;}
