const promotions=Array.isArray(d.promotions)?d.promotions.slice(0,200).filter(plainObject).map(r=>({id:String(r.id||'PR-'+Math.random()).slice(0,60),name:String(r.name||'Offre').slice(0,80),type:['percent','fixed'].includes(r.type)?r.type:'percent',value:integer(r.value,1,9999)??10,scope:['all','H','F','P','product'].includes(r.scope)?r.scope:'all',productId:seeds.has(r.productId)?r.productId:'',start:/^\d{4}-\d{2}-\d{2}$/.test(r.start||'')?r.start:'',end:/^\d{4}-\d{2}-\d{2}$/.test(r.end||'')?r.end:'',active:r.active!==false,createdAt:String(r.createdAt||now())})):[];
const packs={};if(plainObject(d.packs))for(const [id,entry] of Object.entries(d.packs)){if(!packIDs().includes(id)||!Array.isArray(entry?.components))continue;const unique=new Set();packs[id]={components:entry.components.slice(0,12).filter(x=>seeds.has(x.id)&&seeds.get(x.id).category!=='P'&&integer(x.quantity,1,20)!==null&&!unique.has(x.id)&&unique.add(x.id)).map(x=>({id:x.id,quantity:x.quantity}))}}
