const returns=Array.isArray(d.returns)?d.returns.slice(0,1000).filter(x=>plainObject(x)&&orders.some(o=>o.id===x.orderId)&&integer(x.lineIndex,0,100)!==null&&integer(x.quantity,1,999)!==null).map(x=>({id:String(x.id||'RET').slice(0,60),orderId:x.orderId,lineIndex:Number(x.lineIndex),quantity:Number(x.quantity),restocked:x.restocked===true,reason:String(x.reason||'').slice(0,140),at:String(x.at||now())})):[];
